<?php require_once __DIR__.'/includes/bootstrap.php';require_role('business');$bq=db()->prepare('SELECT * FROM businesses WHERE owner_user_id=? LIMIT 1');$bq->execute([$_SESSION['user_id']]);$b=$bq->fetch();if(!$b)exit('No business profile.');$q=db()->prepare("SELECT t.*,u.full_name,s.service_name FROM queue_tickets t JOIN users u ON u.id=t.customer_user_id JOIN services s ON s.id=t.service_id WHERE t.business_id=? AND t.ticket_date=? AND t.status IN ('WAITING','CALLED','IN_SERVICE') ORDER BY t.daily_number");$q->execute([$b['id'],date('Y-m-d')]);$rows=$q->fetchAll();$title='Business queue';require 'includes/header.php';?><h1><?=e($b['business_name'])?> — Queue</h1><section class="panel"><p>Active queue: <?=count($rows)?> ticket(s)</p><table><tr><th>Ticket</th><th>Customer</th><th>Service</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['ticket_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['service_name'])?></td><td><?=e($r['status'])?></td><td><?php $acts=['WAITING'=>['call'=>'Call','skip'=>'Skip'],'CALLED'=>['start'=>'Start service'],'IN_SERVICE'=>['complete'=>'Complete']];foreach(($acts[$r['status']]??[]) as $a=>$label):?><form class="inline" method="post" action="queue_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="ticket_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="<?=$a?>"><button><?=$label?></button></form><?php endforeach;?></td></tr><?php endforeach;?></table></section><?php require 'includes/footer.php';?>